// Solaria process placement prelude (ADR 0014). Generated by Solaria; don't
// edit. The launcher calls clone(), then isolate() before anything else:
// clone() fetches the repositories the run works on, and isolate() builds
// the environment the run gets from isolation.json and creates the run's
// scratch directory. Nothing from the caller's environment reaches the run
// unless isolation.json names it.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const win = process.platform === "win32";

// lookup reads a variable the way the OS does: case-insensitively on
// Windows.
function lookup(env, name) {
  if (!win) return env[name];
  const want = name.toUpperCase();
  for (const [k, v] of Object.entries(env)) {
    if (k.toUpperCase() === want) return v;
  }
  return undefined;
}

function which(bin, pathVar, pathext) {
  const exts = win ? ["", ...(pathext || ".COM;.EXE;.BAT;.CMD").split(";").filter(Boolean)] : [""];
  for (const dir of (pathVar || "").split(path.delimiter)) {
    if (!dir) continue;
    for (const ext of exts) {
      const p = path.join(dir, bin + ext);
      try {
        if (!fs.statSync(p).isFile()) continue;
        if (!win) fs.accessSync(p, fs.constants.X_OK);
        return p;
      } catch {
        // Not here; keep looking.
      }
    }
  }
  return null;
}

// parseDotenv reads a dotenv file as Solaria does (internal/secrets).
export function parseDotenv(text) {
  const out = {};
  const lines = text.split(/\r?\n/);
  for (let n = 1; n <= lines.length; n++) {
    let line = lines[n - 1].trim();
    if (line === "" || line.startsWith("#")) continue;
    if (line.startsWith("export ")) line = line.slice("export ".length);
    const eq = line.indexOf("=");
    const name = eq < 0 ? "" : line.slice(0, eq).trim();
    if (eq < 0 || name === "") throw new Error(`line ${n}: want NAME=value`);
    let value = line.slice(eq + 1).trim();
    if (value.length >= 2 && value[0] === "'" && value.at(-1) === "'") {
      value = value.slice(1, -1);
    } else if (value.length >= 2 && value[0] === '"' && value.at(-1) === '"') {
      try {
        value = JSON.parse(value);
      } catch (err) {
        throw new Error(`line ${n}: ${err.message}`);
      }
    } else {
      const i = value.indexOf(" #");
      if (i >= 0) value = value.slice(0, i).trim();
    }
    out[name] = value;
  }
  return out;
}

// secretSource returns where secrets come from: the dotenv file, or the
// caller's environment.
function secretSource(spec, caller) {
  if (!spec.dotenv) return { values: caller, where: "the environment variables" };
  let text = "";
  try {
    text = fs.readFileSync(spec.dotenv, "utf8");
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }
  try {
    return { values: parseDotenv(text), where: spec.dotenv };
  } catch (err) {
    throw new Error(`${spec.dotenv}: ${err.message}`);
  }
}

// clone clones the repositories isolation.json lists into
// repositories/<name> in workspace (ADR 0017). git gets a scratch HOME and
// no system configuration, so none of the caller's git setup applies, and
// a repository's token reaches it only as an HTTP header for that
// repository's host: never in its arguments, the URL or its output, and
// never in the run's environment.
export function clone(spec, workspace) {
  const repos = spec.repositories ?? [];
  if (repos.length === 0) return;
  const caller = { ...process.env };
  const { values, where } = secretSource(spec, caller);
  const base = { GIT_CONFIG_NOSYSTEM: "1", GIT_TERMINAL_PROMPT: "0" };
  for (const name of [...spec.pass, "PATH", "PATHEXT", "SYSTEMROOT"]) {
    const v = lookup(caller, name);
    if (v && name !== "ANTHROPIC_API_KEY") base[name] = v;
  }
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "solaria-clone-"));
  try {
    for (const r of repos) {
      const dest = path.join(workspace, "repositories", r.name);
      if (fs.existsSync(dest)) {
        throw new Error(`repositories/${r.name} already exists in the workspace; remove it, or start the run in a fresh workspace`);
      }
      const env = { ...base, HOME: home, USERPROFILE: home };
      if (r.secretRef) {
        const token = lookup(values, r.secretRef);
        if (!token) throw new Error(`secret not set in ${where}: ${r.secretRef}, for repository ${r.name}`);
        env.GIT_CONFIG_COUNT = "1";
        env.GIT_CONFIG_KEY_0 = `http.${new URL(r.url).origin}/.extraHeader`;
        env.GIT_CONFIG_VALUE_0 = "Authorization: Basic " + Buffer.from(`x-access-token:${token}`).toString("base64");
      }
      const args = ["clone", "--quiet"];
      if (r.depth) args.push("--depth", String(r.depth));
      if (r.ref) args.push("--branch", r.ref);
      args.push("--", r.url, dest);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      const res = spawnSync("git", args, { env, stdio: ["ignore", "ignore", "pipe"], encoding: "utf8" });
      if (res.error) throw new Error(`can't run git to clone repository ${r.name}: ${res.error.message}`);
      if (res.status !== 0) {
        fs.rmSync(dest, { recursive: true, force: true });
        throw new Error(`git couldn't clone repository ${r.name} from ${r.url}: ${res.stderr.trim()}`);
      }
    }
  } finally {
    fs.rmSync(home, { recursive: true, force: true });
  }
}

// isolate returns the run's environment, its scratch directory, and a
// cleanup function that removes the scratch directory. cacheDir holds
// package downloads across runs.
export function isolate(spec, { cacheDir }) {
  const caller = { ...process.env };
  const env = {};
  for (const name of spec.pass) {
    const v = lookup(caller, name);
    if (v !== undefined && v !== "") env[name] = v;
  }

  const dirs = [path.dirname(process.execPath)];
  const missing = [];
  for (const bin of spec.binaries) {
    const p = which(bin, lookup(caller, "PATH"), lookup(caller, "PATHEXT"));
    if (p) dirs.push(path.dirname(p));
    else missing.push(bin);
  }
  if (missing.length > 0) throw new Error(`not found on PATH: ${missing.join(", ")}`);
  dirs.push(...(spec.path ?? []));
  if (win) {
    const root = lookup(caller, "SYSTEMROOT") || "C:\\Windows";
    dirs.push(path.join(root, "System32"), root);
  } else {
    dirs.push("/usr/bin", "/bin");
  }
  env.PATH = [...new Set(dirs)].join(path.delimiter);

  const { values, where } = secretSource(spec, caller);
  const renamed = spec.secretEnv || {};
  const needed = [...new Set([...spec.secrets, ...Object.values(renamed)])].sort();
  const unset = needed.filter((n) => !lookup(values, n));
  if (unset.length > 0) throw new Error(`secrets not set in ${where}: ${unset.join(", ")}`);
  for (const n of spec.secrets) env[n] = lookup(values, n);
  for (const [v, n] of Object.entries(renamed)) env[v] = lookup(values, n);

  Object.assign(env, spec.set);

  const root = fs.mkdtempSync(path.join(os.tmpdir(), "solaria-run-"));
  for (const [name, rel] of Object.entries(spec.scratch)) {
    const dir = path.join(root, ...rel.split("/"));
    fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    env[name] = dir;
  }
  for (const [name, rel] of Object.entries(spec.cache)) {
    const dir = path.join(cacheDir, ...rel.split("/"));
    fs.mkdirSync(dir, { recursive: true });
    env[name] = dir;
  }
  const cleanup = () => fs.rmSync(root, { recursive: true, force: true });
  return { env, root, cleanup };
}

// adopt replaces this process's own environment with env, so nothing it
// starts can inherit the caller's.
export function adopt(env) {
  for (const k of Object.keys(process.env)) delete process.env[k];
  Object.assign(process.env, env);
}
